let homeTab='Overview',profileTab='About';
let artist={name:'Alex James',role:'Independent artist',location:'London, UK',genre:'Alternative R&B · Neo-soul',bio:'Making honest music for late nights and new beginnings. Alex James blends warm vocals, stripped-back production and stories drawn from everyday life. Currently writing and preparing a debut single, First Light.',photo:'/dashboard-preview/assets/artist-photo.jpg',cover:'/dashboard-preview/assets/artist-cover.jpg',goal:'Release my first music',stage:'Just starting',hours:3,budget:100,links:[{label:'Instagram',url:''},{label:'Spotify',url:''},{label:'YouTube',url:''}]};
try{const saved=JSON.parse(localStorage.getItem('uniify-preview-artist-v2'));if(saved&&typeof saved.name==='string'&&Array.isArray(saved.links))artist={...artist,...saved}}catch{}
const tasks=[
 {id:'bio',title:'Complete your artist biography',reason:'Build a consistent artist identity.',effort:30,phase:0,steps:['Write a short introduction: your artist name, sound and story.','Add one sentence about the music you are making now.','Save a concise biography you can use on your profiles.'],criteria:'A short biography is written and ready to use.',why:'You’re building your artist identity. A clear introduction helps listeners and collaborators understand your music.',next:'Review your artist profiles'},
 {id:'song',title:'Choose your debut single',reason:'Give your first release a clear starting point.',effort:45,phase:0,steps:['Listen back to your demos and shortlist two or three songs.','Choose the track that best introduces your sound and feels realistic to finish.','Write down the working title and what needs to happen before recording.'],criteria:'You have chosen one song and noted what it needs before recording.',why:'You want to release your first music. Choosing the song comes before recording costs, artwork or promotion.',next:'Prepare for your recording session'},
 {id:'options',title:'Explore recording options',reason:'Find an approach within your £100 budget.',effort:30,phase:0,steps:['Compare a home recording setup, a local studio and a producer you trust.','Note what each option includes and ask for an actual quote.','Keep your total recording and release costs within your £100 budget.'],criteria:'At least two recording options and their costs are recorded.',why:'You have £100 available. Comparing options now helps you make a realistic plan before committing to a session.',next:'Choose your recording approach'},
 {id:'record',title:'Prepare for your recording session',reason:'Your song is chosen. Make the most of your session.',effort:45,phase:1,depends:'song',steps:['Finalise the lyrics and make a rough guide recording.','Check your preferred key, tempo and arrangement.','List what to bring and confirm the session costs before booking.'],criteria:'Your lyrics, arrangement and session checklist are ready.',why:'You’ve selected your debut single, so recording preparation is now a practical next step.',next:'Record and review your single'},
 {id:'credits',title:'Confirm your credits and rights',reason:'Agree who contributed before delivery.',effort:30,phase:2,depends:'record',steps:['List each writer, performer and producer.','Confirm ownership and agreements with everyone involved.','Keep the agreed credits with your release notes.'],criteria:'Contributors and ownership records are confirmed.',why:'Your recording needs accurate credits before it can be delivered.',next:'Prepare your release delivery'}
];
let state={done:[],deferred:[],blockers:{},edited:{},checkin:false},filter='All',selectedDay=5,lastChange='',lastUndo=null;
const main=document.querySelector('main'),dialog=document.querySelector('dialog');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const view=()=>[...tabs.map(t=>t[0]),'profile'].includes(location.hash.slice(1))?location.hash.slice(1):'home';
const ready=t=>!t.depends||state.done.includes(t.depends);
const title=t=>state.edited[t.id]||t.title;
const priorities=()=>tasks.filter(t=>ready(t)&&!state.done.includes(t.id)&&!state.deferred.includes(t.id)&&!state.blockers[t.id]).slice(0,3);
function nav(){for(const c of ['.desktop-nav','.bottom-nav'])document.querySelector(c).innerHTML=tabs.map(([id,label])=>`<a href="#${id}" ${view()===id?'class="active" aria-current="page"':''}>${icon(id)}<span>${label}</span></a>`).join('');document.querySelector('#page-label').textContent=view()==='profile'?'Artist profile':tabs.find(t=>t[0]===view())[1];document.querySelectorAll('.desktop-nav a').forEach(a=>{a.title=a.textContent.trim();a.setAttribute('aria-label',a.textContent.trim())})}
const percent=()=>40+state.done.length*10;
const bar=()=>`<div class="bar" role="progressbar" aria-label="Foundation milestone progress" aria-valuenow="${percent()}" aria-valuemin="0" aria-valuemax="100"><span style="width:${percent()}%"></span></div>`;
const meta=t=>`<div class="metadata"><span class="cost">${icon('leaf')}Free</span><span>${icon('clock')}${t.effort} min</span>${state.blockers[t.id]?'<span>Blocked</span>':''}</div>`;
function notice(){return lastChange?`<div class="change-notice">${icon('check')}<div><strong>Your roadmap has moved forward</strong><p>${esc(lastChange)}</p></div><button class="text-button" data-undo>Undo</button></div>`:''}
function priority(t,i){return `<article class="priority"><span class="number">0${i+1}</span><span class="priority-symbol" aria-hidden="true">${icon(t.id==='bio'?'profile':t.id==='song'?'music':t.id==='options'?'discover':'calendar')}</span><button class="priority-main" data-task="${t.id}"><h3>${esc(title(t))}</h3><p>${esc(t.reason)}</p>${meta(t)}</button><button class="task-open" data-task="${t.id}" aria-label="Open ${esc(title(t))}">${icon('chevron')}</button></article>`}
function week(){return `<div class="week">${['M','T','W','T','F','S','S'].map((d,i)=>`<button data-day="${i}" aria-label="${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'][i]}, ${23+i} November" aria-pressed="${i===selectedDay}" class="${i===selectedDay?'selected':''}"><small>${d}</small>${23+i}</button>`).join('')}</div>`}
function release(){return `<div class="context-card release-card"><div class="section-heading"><h2>Your next release</h2><a href="#releases" class="text-button">View plan</a></div><div class="release-art"><img src="/dashboard-preview/assets/cover.jpg" alt="Colourfully lit musician"><span class="art-label">First Light.</span></div><div class="release-type">DEBUT SINGLE</div><div class="release-info"><div><h3>First Light</h3><small>Target · 22 January 2027</small></div><span class="chip">Preparation</span></div>${bar()}<div class="release-bottom"><span>Release preparation</span><span>${percent()}%</span></div></div>`}
function home(){const first=priorities()[0];return `<div class="greeting"><div><span class="welcome-date">SATURDAY, 28 NOVEMBER</span><h1>Welcome back, ${esc(artist.name.split(' ')[0])}.</h1><p>First Light is in preparation. Here’s your week.</p></div><button class="secondary" data-checkin>${icon('calendar')}Weekly check-in</button></div>${notice()}<div class="workspace-tabs" role="tablist" aria-label="Home views">${['Overview','This week','Activity'].map(t=>`<button role="tab" data-home-tab="${t}" aria-selected="${homeTab===t}" class="${homeTab===t?'selected':''}" id="home-tab-${t.replace(' ','-')}" aria-controls="home-content">${t}</button>`).join('')}</div><div id="home-content" role="tabpanel" aria-labelledby="home-tab-${homeTab.replace(' ','-')}">${homeTab==='Activity'?activityView():homeTab==='This week'?`<div class="week-focus"><div class="section-heading"><h2>Your week, in focus</h2><span>3 hours available</span></div><div class="weekly-strip">${week()}</div><div class="priorities">${priorities().map(priority).join('')}</div><button class="secondary" data-checkin>Review your week</button></div>`:`<div class="dashboard"><div class="main-column"><section class="release-spotlight"><div class="spotlight-copy"><span class="eyebrow">YOUR FIRST RELEASE</span><h2>First Light<span class="release-dot">.</span></h2><p>Single · In preparation</p><a class="spotlight-link" href="#releases">Open release plan ${icon('plus')}</a><div class="spotlight-footer"><span class="spotlight-avatar">${artist.photo?`<img src="${esc(artist.photo)}" alt="">`:initials()}</span><span>${esc(artist.name)}<small>Independent artist</small></span><span class="spotlight-date">22 JAN<br><small>TARGET RELEASE</small></span></div></div><div class="record-art" aria-hidden="true"><div class="record-label"><span>${esc(artist.name.toUpperCase())}</span><strong>First<br>Light.</strong><span>DEBUT SINGLE · 01</span></div></div></section><section class="priorities-section"><div class="section-heading"><div><h2>Your next moves</h2><p>Priorities for your debut single.</p></div><a class="text-button" href="#roadmap">All actions</a></div><div class="priorities">${priorities().map(priority).join('')||'<div class="resource"><h3>You’re up to date.</h3><p>Check in to plan what comes next.</p></div>'}</div></section><section class="manager-note"><span class="note-icon">${icon('music')}</span><div><span class="eyebrow">A NOTE FOR YOU</span><p>${state.done.includes('song')?'Song selected. Get your lyrics and arrangement ready before booking a studio.':'Choose the song first. Recording, artwork and promotion can follow when the creative direction is clear.'}</p></div></section></div><aside class="context-column"><section class="milestone compact-milestone"><div class="section-heading"><h2>Your foundations</h2><span class="phase-indicator">IN PROGRESS</span></div><div class="progress-dial"><svg viewBox="0 0 144 144" role="img" aria-label="${percent()} percent of foundation milestones complete"><circle class="dial-track" cx="72" cy="72" r="59"/><circle class="dial-fill" cx="72" cy="72" r="59" stroke-dasharray="${percent()*3.707} 370.7"/></svg><span>${percent()}<small>%</small></span></div><h3>Building your foundations</h3><p>${4+state.done.length} of 10 milestones complete</p><a href="#progress" class="text-button">See your progress</a></section><section class="context-card week-card"><div class="section-heading"><h2>Your week</h2><span>November</span></div>${week()}<div class="calendar-caption"><span class="session-dot"></span><div><strong>${selectedDay===5?'A session for your single':selectedDay===6?'Weekly review':'Time for one small step'}</strong><p>${selectedDay===5?'Today · 45 minutes':selectedDay===6?'Sunday · 15 minutes':'Choose a roadmap action'}</p></div></div></section><section class="checkin mini-checkin"><div class="checkin-head"><h3>${state.checkin?'Week reviewed':'A quick check-in?'}</h3>${icon('calendar')}</div><p>${state.checkin?'Your reflection is saved in this preview.':'What’s moving? What’s getting in the way?'}</p><button class="text-button" data-checkin>${state.checkin?'Review your check-in':'Review your week'}</button></section></aside></div>`}</div>`}
function taskRow(t){const done=state.done.includes(t.id),locked=!ready(t);return `<article class="roadmap-task ${done?'done':''} ${locked?'locked':''}"><span class="status-circle ${done?'done':''}">${done?icon('check'):locked?icon('lock'):''}</span><button class="priority-main" data-task="${t.id}"><h3>${esc(title(t))}</h3><p>${esc(locked?'Unlocks after '+title(tasks.find(x=>x.id===t.depends)):t.reason)}</p>${meta(t)}</button><span class="chip">${done?'Done':state.blockers[t.id]?'Blocked':state.deferred.includes(t.id)?'Later':locked?'Upcoming':'Ready'}</span></article>`}
function roadmap(){const visible=tasks.filter(t=>filter==='All'||filter==='Ready'&&ready(t)&&!state.done.includes(t.id)&&!state.deferred.includes(t.id)&&!state.blockers[t.id]||filter==='Done'&&state.done.includes(t.id)||filter==='Later'&&state.deferred.includes(t.id));return `<div class="view-head"><h1>A plan that grows with you.</h1><p>Your first release, one practical step at a time.</p></div>${notice()}<div class="roadmap-tools"><div class="segmented" aria-label="Filter roadmap">${['All','Ready','Done','Later'].map(f=>`<button class="${f===filter?'active':''}" data-filter="${f}" aria-pressed="${f===filter}">${f}</button>`).join('')}</div><span class="roadmap-summary">3 hours this week · £100 available</span></div>${['Build your foundations','Make the music','Prepare your release'].map((p,i)=>{const ts=visible.filter(t=>t.phase===i);return ts.length?`<section class="phase"><div class="phase-head"><span class="phase-dot">${i+1}</span><h2>${p}</h2><small>${i===0?'Your current phase':'What comes next'}</small></div>${ts.map(taskRow).join('')}</section>`:''}).join('')||'<div class="resource"><h3>No actions in this view.</h3><p>Choose another filter to explore your roadmap.</p></div>'}`}
function releases(){return `<div class="view-head"><h1>Give your music its moment.</h1><p>A clear plan for your debut single.</p></div><div class="dashboard"><section class="main-column"><section class="milestone"><div class="milestone-top"><span class="eyebrow">First Light · Single</span>${icon('releases')}</div><h2>Your first release starts here.</h2><p>22 January 2027 · £100 budget · Preparation</p><div class="milestone-count"><span>${4+state.done.length} of 10 preparation milestones</span><strong>${percent()}%</strong></div>${bar()}</section>${tasks.slice(0,3).map(taskRow).join('')}</section><aside class="context-column"><section class="context-card"><div class="section-heading"><h2>Keep the budget in view</h2>${icon('wallet')}</div><div class="stats"><div><h2>£100</h2><small>Available</small></div><div><h2>£0</h2><small>Recorded spend</small></div></div><p class="progress-label">Compare recording costs before making a commitment.</p></section><section class="insight"><div class="insight-title">${icon('sparkles')}<h3>Start with the song</h3></div><p>Creative readiness shapes the plan. Your chosen dates stay yours when priorities change.</p></section></aside></div>`}
function progress(){return `<div class="view-head"><h1>Look how far you’ve come.</h1><p>Your work and your outcomes, with room to keep growing.</p></div><div class="stats"><section class="stat"><p>Foundation milestones</p><strong>${4+state.done.length}/10</strong><p>Completed</p></section><section class="stat"><p>Music released</p><strong>0</strong><p>Your debut is in preparation</p></section><section class="stat"><p>Recorded spend</p><strong>£0</strong><p>Of £100 available</p></section></div><section class="resource"><h2>Your recent progress</h2>${state.done.length?state.done.map(id=>`<div class="roadmap-task"><span class="status-circle done">${icon('check')}</span><div><h3>${esc(title(tasks.find(t=>t.id===id)))}</h3><p>Completed in this design preview</p></div></div>`).join(''):'<p>Your artist name, goal, budget and weekly availability are set. Complete a priority to record your next milestone.</p>'}</section><section class="insight"><div class="insight-title">${icon('progress')}<h3>Progress is more than a task count.</h3></div><p>Audience, engagement and income belong alongside the work you do. There are no audience results recorded for this fictional artist yet.</p></section>`}
function discover(){return `<div class="view-head"><h1>A little knowledge. A clearer path.</h1><p>Practical guidance for the stage you’re at.</p></div>${[['Your first release','What to prepare before sending music to a distributor.','Have your final audio, artwork, song title, credits and release date ready. Confirm delivery requirements with your chosen distributor and leave time to resolve issues.'],['Know your rights and credits','Start with a clear record of who created what.','List the writers, performers and producers involved. Discuss ownership and permissions before release, keep written agreements and seek qualified advice when needed.'],['Make the most of a small budget','Spend with a purpose and keep free options open.','List essential recording and delivery costs first. Compare actual quotes, keep a contingency, and avoid paying for promotion before the music is ready.']].map(([a,b,c])=>`<article class="resource"><span class="eyebrow">For your first release</span><h2 style="margin-top:9px">${a}</h2><p>${b}</p><details><summary>Read the guide</summary><p>${c}</p></details></article>`).join('')}`}
function render(){nav();main.innerHTML=({home,roadmap,releases,progress,discover,profile}[view()])();syncIdentity();}
function open(content,label='Your next action'){dialog.innerHTML=`<div class="dialog-header"><button class="icon-button dialog-back" data-close aria-label="Back to workspace">${icon('back')}</button><small>${label}</small><button class="icon-button desktop-close" data-close aria-label="Close panel">${icon('close')}</button><span class="dialog-spacer" aria-hidden="true"></span></div><div class="dialog-content">${content}</div>`;if(!dialog.open)dialog.showModal();document.body.style.overflow='hidden';dialog.scrollTop=0;}
function close(){dialog.close();document.body.style.overflow='';}dialog.addEventListener('close',()=>document.body.style.overflow='');dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left)close()}});
function openTask(id){const t=tasks.find(t=>t.id===id),done=state.done.includes(id),locked=!ready(t);open(`<span class="eyebrow">${['Artist foundations','Recording preparation','Release preparation'][t.phase]}</span><h2 id="dialog-title">${esc(title(t))}</h2><div class="detail-meta"><span>${icon('clock')}${t.effort} minutes</span><span>${icon('leaf')}Free action</span></div><div class="reason"><strong>Why this matters for you</strong><p>${esc(t.why)}</p></div><h3>Make it happen</h3><ol class="steps">${t.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><div class="criteria"><span>You’re done when</span><p>${esc(t.criteria)}</p></div><div class="unlock">${icon(locked?'lock':'unlock')}<div><strong>${locked?'Complete the previous step first':'What comes next'}</strong><small>${esc(locked?title(tasks.find(x=>x.id===t.depends)):t.next)}</small></div></div>${state.blockers[id]?`<div class="reason"><strong>Your blocker</strong><p>${esc(state.blockers[id])}</p></div>`:''}<div class="dialog-actions"><button class="primary" data-complete="${id}" ${locked?'disabled':''}>${icon('check')}${done?'Reopen this action':'Mark as complete'}</button><div class="minor-actions"><button data-defer="${id}">${state.deferred.includes(id)?'Bring back':'Do this later'}</button><button data-blocker="${id}">${state.blockers[id]?'Update blocker':'I’m blocked'}</button><button data-edit="${id}">Edit</button></div></div>`)}
function snapshot(){lastUndo=JSON.stringify(state)}
function complete(id){snapshot();if(state.done.includes(id)){state.done=state.done.filter(x=>x!==id);lastChange='Action reopened. Dependent steps now need review.'}else{state.done.push(id);state.deferred=state.deferred.filter(x=>x!==id);delete state.blockers[id];lastChange=id==='song'?'You chose your debut single. Recording preparation is now ready.':`${title(tasks.find(t=>t.id===id))} is complete. Your next priorities have been reviewed.`}close();render();notify('Progress updated. Your next move is ready.');}
function notify(message){const t=document.querySelector('.toast');t.textContent=message;t.hidden=false;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.hidden=true,4200)}
function checkin(){open(`<span class="eyebrow">A moment to reflect</span><h2 id="dialog-title">How’s your week going?</h2><p>A little reflection helps keep the next steps realistic.</p><form id="checkin-form"><label class="field">What moved forward?<textarea name="progress" placeholder="A small win counts, too.">${esc(state.reflection||'')}</textarea></label><label class="field">What’s getting in the way?<textarea name="blocker" placeholder="Time, confidence, costs, or something else…">${esc(state.weekBlocker||'')}</textarea></label><label class="field">Time available next week<select name="hours"><option>3 hours</option><option>1 hour</option><option>5 hours</option><option>I’m not sure yet</option></select></label><button class="primary" type="submit" style="width:100%;margin-top:12px">Save my check-in</button></form>`,'Your weekly check-in')}
function initials(){return esc(artist.name.split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('')||'A')}
function saveArtist(){try{localStorage.setItem('uniify-preview-artist-v2',JSON.stringify(artist))}catch{notify('Your changes are in this preview, but this browser could not save them.')}}
function syncIdentity(){for(const el of document.querySelectorAll('[data-identity-photo]'))el.innerHTML=artist.photo?`<img src="${esc(artist.photo)}" alt="">`:initials();document.querySelector('.profile-button strong').textContent=artist.name;document.querySelector('.profile-button small').textContent=artist.role;document.querySelector('.profile-nav').classList.toggle('active',view()==='profile');}
function activityView(){return `<section class="activity-feed"><div class="section-heading"><h2>Recent activity</h2><span>YOUR WORK, RECORDED</span></div>${state.done.map(id=>`<div class="activity-item"><span class="activity-icon">${icon('check')}</span><div><h3>${esc(title(tasks.find(t=>t.id===id)))}</h3><p>Completed in this preview</p></div><small>Just now</small></div>`).join('')}${state.checkin?'<div class="activity-item"><span class="activity-icon">'+icon('calendar')+'</span><div><h3>Weekly check-in saved</h3><p>Your reflection is ready to revisit.</p></div></div>':''}<div class="activity-item"><span class="activity-icon">${icon('releases')}</span><div><h3>First Light added to your releases</h3><p>Preparation · Target 22 January 2027</p></div><small>28 Nov</small></div><div class="activity-item"><span class="activity-icon">${icon('profile')}</span><div><h3>Your starting point is set</h3><p>Goal, budget and weekly availability recorded.</p></div><small>28 Nov</small></div></section>`}
function profile(){return `<div class="profile-page"><div class="profile-cover ${artist.cover?'':'no-cover'}">${artist.cover?`<img src="${esc(artist.cover)}" alt="Artist cover image">`:'<span class="cover-placeholder">Your sound. Your space.</span>'}<button class="cover-change" data-image-menu="cover" aria-expanded="false" aria-controls="cover-menu">${icon('camera')}<span>Edit cover</span></button><div class="image-menu cover-menu" id="cover-menu" hidden><button data-upload="cover">${icon('upload')}Change cover</button><button data-remove-image="cover">${icon('trash')}Remove cover</button></div></div><div class="profile-heading"><div class="profile-portrait"><button class="portrait-image" data-image-menu="photo" aria-label="Edit profile photo" aria-expanded="false" aria-controls="photo-menu">${artist.photo?`<img src="${esc(artist.photo)}" alt="${esc(artist.name)}">`:`<span>${initials()}</span>`}</button><button class="portrait-edit" data-image-menu="photo" aria-label="Change profile photo" aria-expanded="false" aria-controls="photo-menu">${icon('camera')}</button><div class="image-menu" id="photo-menu" hidden><button data-upload="photo">${icon('upload')}Change photo</button><button data-remove-image="photo">${icon('trash')}Remove photo</button></div></div><div class="profile-title"><h1>${esc(artist.name)}<span class="release-dot">.</span></h1><p>${esc(artist.role)}<span>·</span>${esc(artist.location)}</p></div><button class="secondary" data-edit-profile>${icon('edit')}Edit profile</button></div><div class="workspace-tabs profile-tabs" role="tablist" aria-label="Artist profile sections">${['About','Links','Career'].map(t=>`<button role="tab" data-profile-tab="${t}" class="${profileTab===t?'selected':''}" aria-selected="${profileTab===t}" id="profile-tab-${t}" aria-controls="profile-content">${t}</button>`).join('')}</div><section id="profile-content" role="tabpanel" aria-labelledby="profile-tab-${profileTab}">${profileTab==='Links'?profileLinks():profileTab==='Career'?profileCareer():`<div class="profile-grid"><section class="bio-section"><span class="eyebrow">THE ARTIST</span><h2>A little about ${esc(artist.name.split(' ')[0])}.</h2><p class="artist-bio">${esc(artist.bio)||'Tell your story. Add a short biography to introduce your music.'}</p><div class="artist-details"><div><span>Sound</span><strong>${esc(artist.genre)||'Not added'}</strong></div><div><span>Based in</span><strong>${esc(artist.location)||'Not added'}</strong></div><div><span>Current focus</span><strong>${esc(artist.goal)}</strong></div></div><button class="text-button" data-edit-profile>Update your story</button></section><aside class="profile-side"><div class="profile-mini-release"><span class="eyebrow">IN THE WORKS</span><div class="mini-release-art"><img src="/dashboard-preview/assets/cover.jpg" alt="Release artwork"><span>${icon('releases')}</span></div><h3>First Light</h3><p>Debut single · In preparation</p><a class="text-button" href="#releases">View release plan</a></div><div class="profile-links-summary"><div class="section-heading"><h3>Find me online</h3><button class="text-button" data-show-links>Edit links</button></div>${artist.links.filter(l=>/^https?:\/\//i.test(l.url)).slice(0,3).map(l=>`<a href="${esc(l.url)}" target="_blank" rel="noopener noreferrer">${platformIcon(l.label)}<span>${esc(l.label)}</span></a>`).join('')||'<p>Add your social and streaming links.</p>'}</div></aside></div>`}</section><input type="file" id="cover-upload" data-image-input="cover" accept="image/jpeg,image/png,image/webp" hidden><input type="file" id="photo-upload" data-image-input="photo" accept="image/jpeg,image/png,image/webp" hidden></div>`}
function platformIcon(label){return icon(/spotify|music|soundcloud|bandcamp/i.test(label)?'music':/instagram/i.test(label)?'instagram':/youtube/i.test(label)?'play':'link')}
function profileLinks(){const platforms=['Instagram','Spotify','YouTube','TikTok','Facebook','Apple Music','SoundCloud','Bandcamp','Other'];return `<div class="links-page"><div class="profile-section-intro"><span class="eyebrow">YOUR MUSIC, CONNECTED</span><h2>Make it easy to find you.</h2><p>Keep your social profiles, music and other links together.</p></div><form id="social-form"><div class="social-rows">${artist.links.map((l,i)=>`<div class="social-row"><span class="social-icon">${platformIcon(l.label)}</span><div class="social-fields"><label>Platform<select name="platform-${i}">${platforms.map(p=>`<option ${p===l.label||p==='Other'&&!platforms.includes(l.label)?'selected':''}>${p}</option>`).join('')}</select></label>${!platforms.slice(0,-1).includes(l.label)?`<label>Label<input name="label-${i}" value="${esc(l.label)}" maxlength="40" placeholder="e.g. Press kit"></label>`:''}<label class="url-field">Link<input name="url-${i}" type="url" value="${esc(l.url)}" placeholder="https://" maxlength="1000"></label></div><button class="icon-button" type="button" data-delete-link="${i}" aria-label="Remove ${esc(l.label)} link">${icon('close')}</button></div>`).join('')}</div><div class="links-actions"><button class="secondary" data-add-social type="button">${icon('plus')}Add a link</button><button class="primary" type="submit">Save links</button></div><p id="links-status" role="status"></p></form></div>`}
function profileCareer(){return `<div class="career-profile"><div class="profile-section-intro"><span class="eyebrow">YOUR STARTING POINT</span><h2>A plan that fits your life.</h2><p>Your goal and resources help shape the work ahead.</p></div><form id="career-profile-form"><div class="profile-form-grid"><label class="field">Your main goal<select name="goal">${['Release my first music','Grow my audience','Earn more from music','Improve career management'].map(g=>`<option ${g===artist.goal?'selected':''}>${g}</option>`).join('')}</select></label><label class="field">Career stage<select name="stage">${['Just starting','Released music, building an audience','Established independent artist'].map(g=>`<option ${g===artist.stage?'selected':''}>${g}</option>`).join('')}</select></label><label class="field">Hours available per week<input name="hours" type="number" min="0" max="168" step="0.5" value="${artist.hours}" required></label><label class="field">Music budget (£)<input name="budget" type="number" min="0" max="1000000" step="0.01" value="${artist.budget}" placeholder="Unknown"></label></div><button class="primary" type="submit">Save career details</button><p class="form-hint">These details are saved in this local design preview.</p></form></div>`}
function editProfile(){open(`<span class="eyebrow">MAKE IT YOURS</span><h2 id="dialog-title">Edit your profile.</h2><form id="edit-profile-form"><label class="field">Artist name<input name="name" value="${esc(artist.name)}" maxlength="80" required></label><div class="profile-form-grid"><label class="field">Artist role<input name="role" value="${esc(artist.role)}" maxlength="80" required></label><label class="field">Location<input name="location" value="${esc(artist.location)}" maxlength="80"></label></div><label class="field">Your sound<input name="genre" value="${esc(artist.genre)}" maxlength="120" placeholder="e.g. Alternative R&B, Neo-soul"></label><label class="field">Biography<textarea name="bio" maxlength="1500" rows="6">${esc(artist.bio)}</textarea></label><button type="submit" class="primary" style="width:100%">Save profile</button></form>`,'Artist profile')}
function stashLinks(){const f=document.querySelector('#social-form');if(!f)return;artist.links=artist.links.map((l,i)=>{const platform=f.elements['platform-'+i]?.value||l.label;return {label:platform==='Other'?(f.elements['label-'+i]?.value||(!['Instagram','Spotify','YouTube','TikTok','Facebook','Apple Music','SoundCloud','Bandcamp','Other'].includes(l.label)?l.label:'Other')):platform,url:f.elements['url-'+i]?.value||''}})}
function setupShell(){document.querySelector('.brand').insertAdjacentHTML('afterend',`<a class="brand-symbol" href="#home" aria-label="Uniify home"><img src="/dashboard-preview/assets/favicon.png" alt=""></a><button class="sidebar-toggle icon-button" id="sidebar-toggle" aria-label="Collapse sidebar" aria-expanded="true">${icon('panel')}</button>`);document.querySelector('.desktop-nav').insertAdjacentHTML('afterend',`<a class="profile-nav" href="#profile" title="Artist profile">${icon('profile')}<span>Artist profile</span></a>`);document.querySelector('.sidebar-note').remove();document.querySelector('.profile-button .avatar').setAttribute('data-identity-photo','');document.querySelector('.top-avatar').setAttribute('data-identity-photo','');const collapsed=localStorage.getItem('uniify-preview-sidebar')==='collapsed';document.body.classList.toggle('sidebar-collapsed',collapsed);setSidebarControl();syncIdentity()}
function setSidebarControl(){const collapsed=document.body.classList.contains('sidebar-collapsed'),b=document.querySelector('#sidebar-toggle');b.setAttribute('aria-expanded',String(!collapsed));b.setAttribute('aria-label',collapsed?'Expand sidebar':'Collapse sidebar');b.innerHTML=icon(collapsed?'panel-open':'panel');}
function closeImageMenus(){document.querySelectorAll('.image-menu').forEach(m=>m.hidden=true);document.querySelectorAll('[data-image-menu]').forEach(b=>b.setAttribute('aria-expanded','false'))}
async function uploadImage(input){const file=input.files[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024){notify('Choose a JPG, PNG or WebP under 10 MB.');input.value='';return}try{const bitmap=await createImageBitmap(file),cover=input.dataset.imageInput==='cover',w=cover?1600:512,h=cover?560:512,canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;const scale=Math.max(w/bitmap.width,h/bitmap.height),sw=w/scale,sh=h/scale;canvas.getContext('2d').drawImage(bitmap,(bitmap.width-sw)/2,(bitmap.height-sh)/2,sw,sh,0,0,w,h);bitmap.close();artist[cover?'cover':'photo']=canvas.toDataURL('image/jpeg',.88);saveArtist();render();notify(cover?'Cover image updated.':'Profile photo updated.')}catch{notify('That image could not be opened. Try another JPG, PNG or WebP.')}input.value=''}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-close'))close();if(b.dataset.task)openTask(b.dataset.task);if(b.dataset.complete)complete(b.dataset.complete);if(b.dataset.filter){filter=b.dataset.filter;render()}if(b.dataset.day!==undefined){selectedDay=Number(b.dataset.day);render()}if(b.hasAttribute('data-checkin'))checkin();if(b.hasAttribute('data-undo')&&lastUndo){state=JSON.parse(lastUndo);lastUndo=null;lastChange='';render();notify('Last action change undone.')}if(b.dataset.defer){const id=b.dataset.defer;snapshot();state.deferred=state.deferred.includes(id)?state.deferred.filter(x=>x!==id):[...state.deferred,id];lastChange='Your action was moved. Other eligible priorities stay in view.';close();render();notify('Roadmap updated.')}if(b.dataset.blocker){const id=b.dataset.blocker;open(`<h2 id="dialog-title">What’s getting in the way?</h2><p>${esc(title(tasks.find(t=>t.id===id)))}</p><form id="blocker-form" data-id="${id}"><label class="field">Tell us what you need<textarea name="blocker" placeholder="For example, I need help choosing between two demos.">${esc(state.blockers[id]||'')}</textarea></label><button class="primary" type="submit">Save blocker</button></form>`)}if(b.dataset.edit){const id=b.dataset.edit;open(`<h2 id="dialog-title">Make this action yours.</h2><form id="edit-form" data-id="${id}"><label class="field">Action title<input name="title" maxlength="120" required value="${esc(title(tasks.find(t=>t.id===id)))}"></label><button class="primary" type="submit">Save changes</button></form>`)}if(b.hasAttribute('data-profile')){location.hash='profile';if(view()==='profile')render();}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,data=new FormData(f);if(f.id==='checkin-form'){state.checkin=true;state.reflection=data.get('progress');state.weekBlocker=data.get('blocker');close();render();notify('Your check-in is saved in this preview.')}if(f.id==='blocker-form'){snapshot();const id=f.dataset.id;const value=data.get('blocker').trim();if(value)state.blockers[id]=value;else delete state.blockers[id];close();render();notify(value?'Blocker recorded. Other priorities stay available.':'Blocker cleared.')}if(f.id==='edit-form'){const value=data.get('title').trim();if(!value)return;state.edited[f.dataset.id]=value;close();render();notify('Action updated.')}});
function theme(){const dark=document.documentElement.dataset.theme==='dark';document.querySelector('#theme').innerHTML=icon(dark?'sun':'moon');document.querySelector('#theme').setAttribute('aria-label',dark?'Switch to light mode':'Switch to dark mode')};document.querySelector('#theme').onclick=()=>{document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';theme()};document.querySelector('#reset').innerHTML=icon('reset');document.querySelector('#reset').onclick=()=>{state={done:[],deferred:[],blockers:{},edited:{},checkin:false};filter='All';lastChange='';lastUndo=null;render();notify('Preview reset to Alex’s starting point.')};window.addEventListener('hashchange',()=>{filter='All';render();window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true})});theme();setupShell();render();

// Profile editing and navigation belong to this isolated design preview.
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b){if(!e.target.closest('.image-menu'))closeImageMenus();return;}
 if(b.id==='sidebar-toggle'){document.body.classList.toggle('sidebar-collapsed');try{localStorage.setItem('uniify-preview-sidebar',document.body.classList.contains('sidebar-collapsed')?'collapsed':'expanded')}catch{}setSidebarControl()}
 if(b.dataset.homeTab){homeTab=b.dataset.homeTab;render();document.querySelector(`[data-home-tab="${homeTab}"]`).focus({preventScroll:true})}
 if(b.dataset.profileTab){if(profileTab==='Links')stashLinks();profileTab=b.dataset.profileTab;render();document.querySelector(`[data-profile-tab="${profileTab}"]`).focus({preventScroll:true})}
 if(b.hasAttribute('data-edit-profile'))editProfile();
 if(b.hasAttribute('data-show-links')){profileTab='Links';render()}
 if(b.dataset.imageMenu){const id=b.dataset.imageMenu+'-menu',m=document.getElementById(id),show=m.hidden;closeImageMenus();m.hidden=!show;document.querySelectorAll(`[data-image-menu="${b.dataset.imageMenu}"]`).forEach(x=>x.setAttribute('aria-expanded',String(show)))}
 else if(!b.closest('.image-menu'))closeImageMenus();
 if(b.dataset.upload){document.getElementById(b.dataset.upload+'-upload').click();closeImageMenus()}
 if(b.dataset.removeImage){artist[b.dataset.removeImage]='';saveArtist();render();notify(b.dataset.removeImage==='cover'?'Cover removed.':'Profile photo removed.')}
 if(b.hasAttribute('data-add-social')){stashLinks();artist.links.push({label:'Other',url:''});render();document.querySelector('.social-row:last-child input')?.focus()}
 if(b.dataset.deleteLink!==undefined){stashLinks();artist.links.splice(Number(b.dataset.deleteLink),1);render()}
});
document.addEventListener('change',e=>{if(e.target.dataset.imageInput)uploadImage(e.target);if(e.target.matches('#social-form select')){stashLinks();render()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeImageMenus();const tab=e.target.closest('[role=tab]');if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const ts=[...tab.parentElement.querySelectorAll('[role=tab]')],i=ts.indexOf(tab),next=e.key==='Home'?0:e.key==='End'?ts.length-1:(i+(e.key==='ArrowRight'?1:-1)+ts.length)%ts.length;ts[next].click()});
document.addEventListener('submit',e=>{const f=e.target,data=new FormData(f);
 if(f.id==='edit-profile-form'){e.preventDefault();const name=data.get('name').trim(),role=data.get('role').trim();if(!name||!role)return;artist={...artist,name,role,location:data.get('location').trim(),genre:data.get('genre').trim(),bio:data.get('bio').trim()};saveArtist();close();render();notify('Artist profile updated.')}
 if(f.id==='social-form'){e.preventDefault();stashLinks();const invalid=artist.links.some(l=>l.url&&(!/^https?:\/\//i.test(l.url)||(()=>{try{return !new URL(l.url).hostname}catch{return true}})()));if(invalid){document.querySelector('#links-status').textContent='Use a complete http:// or https:// link.';return}saveArtist();document.querySelector('#links-status').textContent='Your links are saved.';notify('Social and streaming links saved.')}
 if(f.id==='career-profile-form'){e.preventDefault();artist.goal=data.get('goal');artist.stage=data.get('stage');artist.hours=Number(data.get('hours'));artist.budget=data.get('budget')===''?null:Number(data.get('budget'));saveArtist();notify('Career details saved in this preview.')}
});
